mapper.select:


		select count(partner_id) from nyehms_cluster_partners where 

		 current_process_Status in (17) 


        AND FLUX_MATCH_CD =  #{filterCriteriaForStatusCode} 



        AND CLUSTER_ID =  #{clusterPartnerId}

select DOCUMENT_ID, MATCH_CD, FUZZY_CLUSTER_ID, CLUSTER_ID, POT_STATENO, DOC_TYPE from (select PARTNER_ID DOCUMENT_ID, FLUX_MATCH_CD MATCH_CD,
'' FUZZY_CLUSTER_ID, PARTNER_CLUSTER_ID CLUSTER_ID, FLUX_POT_STATENO POT_STATENO, 'CLUST_PART' DOC_TYPE,
dbms_random.value rand_order from nyehms_cluster_partners where current_process_Status in (17)
AND flux_MATCH_CD = #{filterCriteriaForStatusCode}
AND CLUSTER_ID = #{clusterPartnerId}
ORDER BY rand_order ) where ROWNUM < 2

		select DIN, CITY PERSON_CITY, FIRST_NAME FNAME, MIDDLE_NAME MNAME, LAST_NAME LNAME, HOME_PHONE, CELL_PHONE, CLUSTER_ID, COUNTY PERSON_COUNTY, ETHNICITY,   MEDRECNO, BIRTH_SEX, STREET PERSON_ADDRESS, STATE PERSON_STATE, ZIPCODE  PERSON_ZIP, NYSID,  CREATE_UID,   PARTNER_ID,       TO_CHAR(DATE_OF_BIRTH, 'MM/DD/YYYY') DATE_OF_BIRTH, TO_CHAR(DATE_OF_DEATH, 'MM/DD/YYYY') DATE_OF_DEATH, TO_CHAR(CREATE_DATE, 'MM/DD/YYYY') CREATE_DATE, RACE_WHITE, RACE_BLACK, race_amerind RACE_INDIAN, RACE_ASIAN, RACE_PACIFIC, RACE_OTHER, RACE_UNKNOWN , PARTNER_CLUSTER_ID,
                COUNTRYOFBIRTH    BIRTH_COUNTRY, CURRENTGENDER    GENDER, PARTNERASSISTANCESTATUS PARTNER_ASSISTANCE_STATUS, CONFIRMPATIENTPREP,CURRENTONPREP

			 from NYEHMS_CLUSTER_PARTNERS std where PARTNER_ID = #{PARTNER_ID}


select PARTNER_TYPE, PARTNERASSISTANCESTATUS, PARTNERKEY, PARTNER_FLAG, PARTNER_FRNUMBER, PART_INACTIVE_FLAG, TO_CHAR(PART_INACTIVE_DATE, 'MM/DD/YYYY') PART_INACTIVE_DATE, DISNUMBER, LEGACY_PARTNER_ID, TO_CHAR(LAST_HIV_NEG_DATE, 'MM/DD/YYYY') LAST_HIV_NEG_DATE, OP_STATENO, OP_CDESSCASEKEY, OP_FRNUMBER, OP_FIELDRECORDKEY, OP_INACTIVE_FLAG, TO_CHAR(OP_DATE_CLOSED, 'MM/DD/YYYY') OP_DATE_CLOSED, TO_CHAR(DATEINITIATED, 'MM/DD/YYYY') DATEINITIATED, TO_CHAR(INTERVIEWDATE, 'MM/DD/YYYY') INTERVIEWDATE, CURRENTONPREP, CONFIRMPATIENTPREP, NOTIFICATIONDATEPIND, TO_CHAR(NOTIFICATIONDATE, 'MM/DD/YYYY') NOTIFICATIONDATE,
CONDITION_1, DISPOSITION1, TO_CHAR(DISPOSITIONDATE1, 'MM/DD/YYYY') DISPOSITIONDATE1, CONDITION_2, DISPOSITION2, TO_CHAR(DISPOSITIONDATE2, 'MM/DD/YYYY') DISPOSITIONDATE2, CONDITION_3, DISPOSITION3, TO_CHAR(DISPOSITIONDATE3, 'MM/DD/YYYY') DISPOSITIONDATE3, CONDITION_4, DISPOSITION4, TO_CHAR(DISPOSITIONDATE4, 'MM/DD/YYYY') DISPOSITIONDATE4,  to_char(FIELDNOTE)
from NYEHMS_CLUSTER_PARTNERS where 



			DOCUMENT_ID = #{DOCUMENT_ID}


			PARTNER_CLUSTER_ID = #{PARTNER_CLUSTER_ID} and CLUSTER_ID = #{CLUSTER_ID}
